const input = $('When Called').first().json || {};
const config = $('Load Config').first().json || {};

let mode = (input.mode || 'n8n_users').toString().trim();
if (mode !== 'n8n_users' && mode !== 'non_users') mode = 'n8n_users';

let filters = input.filters || {};
if (typeof filters === 'string') {
  try { filters = JSON.parse(filters); } catch (e) { filters = {}; }
}
if (typeof filters !== 'object' || Array.isArray(filters) || filters === null) filters = {};

let sampleSize = Number(input.sampleSize);
if (!Number.isFinite(sampleSize) || sampleSize <= 0) sampleSize = Number(config.maxSampleSize) || 10;
const maxSampleSize = Number(config.maxSampleSize) || 20;
if (sampleSize > maxSampleSize) sampleSize = maxSampleSize;
sampleSize = Math.floor(sampleSize);

let excludeRecentDays = Number(input.excludeRecentDays);
if (!Number.isFinite(excludeRecentDays) || excludeRecentDays < 0) excludeRecentDays = Number(config.cooldownDays) || 60;
excludeRecentDays = Math.floor(excludeRecentDays);

return [{ json: { mode, filters, sampleSize, excludeRecentDays, config } }];

const data = $input.first().json;
const { mode, filters, sampleSize, excludeRecentDays, config } = data;

const cooldownField = config.cooldownField || 'last_user_research_invite_date';
const shardField = config.shardField || 'uxr_shard';
const shardCount = Number(config.shardCount) || 4096;

const cutoff = new Date(Date.now() - excludeRecentDays * 24 * 60 * 60 * 1000);
const cutoffTs = Math.floor(cutoff.getTime() / 1000);

const filterDefs = mode === 'n8n_users' ? (config.nUserFilters || []) : (config.nonUserFilters || []);
const defById = {};
for (const d of filterDefs) defById[d.id] = d;

// Cooldown clause: field doesn't exist OR older than cutoff
const cooldownClause = {
  or: [
    { attribute: { field: cooldownField, operator: 'not_exists' } },
    { attribute: { field: cooldownField, operator: 'lt', value: String(cutoffTs) } }
  ]
};

const andClauses = [];

if (mode === 'n8n_users') {
  // Quality gates
  andClauses.push({ attribute: { field: 'email', operator: 'exists' } });
  andClauses.push({ not: { attribute: { field: 'unsubscribed', operator: 'eq', value: 'true' } } });
  andClauses.push({ attribute: { field: 'created_n8n_account', operator: 'eq', value: 'true' } });
  andClauses.push({ attribute: { field: 'confirmed', operator: 'eq', value: 'true' } });
  // Exclude non-user webform signups
  andClauses.push({ not: { and: [
    { attribute: { field: 'origin', operator: 'eq', value: 'user_research_webform' } },
    { or: [
      { attribute: { field: 'n8n_usage', operator: 'eq', value: 'aware' } },
      { attribute: { field: 'n8n_usage', operator: 'eq', value: 'new' } }
    ] },
    { not: { attribute: { field: 'created_n8n_account', operator: 'eq', value: 'true' } } }
  ] } });
} else {
  // Non-users base query
  const base = config.nonUserBaseQuery || {};
  andClauses.push({ attribute: { field: 'email', operator: 'exists' } });
  andClauses.push({ attribute: { field: 'origin', operator: 'eq', value: base.origin || 'user_research_webform' } });
  andClauses.push({ not: { attribute: { field: 'created_n8n_account', operator: 'eq', value: 'true' } } });
  // n8n_usage in selected values (default aware+new)
  let usageVals = filters.n8n_usage;
  if (!Array.isArray(usageVals) || usageVals.length === 0) {
    usageVals = (base.n8n_usage_default) || ['aware', 'new'];
  }
  andClauses.push({ or: usageVals.map(v => ({ attribute: { field: 'n8n_usage', operator: 'eq', value: String(v) } })) });
}

// Cooldown always applied
andClauses.push(cooldownClause);

// User-selected filters (skip n8n_usage in non_users, already handled)
for (const [key, val] of Object.entries(filters)) {
  if (mode === 'non_users' && key === 'n8n_usage') continue;
  if (val === undefined || val === null || val === '') continue;
  const def = defById[key];
  if (Array.isArray(val)) {
    if (val.length === 0) continue;
    andClauses.push({ or: val.map(v => ({ attribute: { field: key, operator: 'eq', value: String(v) } })) });
  } else {
    andClauses.push({ attribute: { field: key, operator: 'eq', value: String(val) } });
  }
}

return [{ json: {
  mode, filters, sampleSize, excludeRecentDays,
  cooldownField, shardField, shardCount,
  baseAndClauses: andClauses,
  attempt: 0,
  maxAttempts: 3,
  shardsUsed: [],
  collected: [],
  totalMatching: 0
} }];

const s = $input.first().json;

// Number of shards to query this attempt. Start with a spread proportional to sampleSize, widen on retries.
const shardsPerAttempt = Math.min(s.shardCount, Math.max(4, s.sampleSize) * (s.attempt + 1) * 2);

const used = new Set(s.shardsUsed || []);
const newShards = [];
let guard = 0;
while (newShards.length < shardsPerAttempt && used.size < s.shardCount && guard < shardsPerAttempt * 20) {
  guard++;
  const shard = Math.floor(Math.random() * s.shardCount);
  if (!used.has(shard)) { used.add(shard); newShards.push(shard); }
}

// Build the full CIO filter with a shard OR-clause for the newly picked shards
const shardClause = { or: newShards.map(sh => ({ attribute: { field: s.shardField, operator: 'eq', value: String(sh) } })) };
const andClauses = s.baseAndClauses.slice();
if (newShards.length > 0) andClauses.push(shardClause);

const cioFilter = { filter: { and: andClauses } };

return [{ json: { ...s, currentShards: newShards, shardsUsed: Array.from(used), cioFilter } }];

const s = $('Pick Shards').first().json;
const pages = $input.all().map(i => i.json);

let error = null;
let rows = [];
for (const p of pages) {
  const status = p.statusCode || 0;
  const body = p.body || p;
  if (status >= 400) {
    error = 'Customer.io API error (HTTP ' + status + '): ' + JSON.stringify(body).slice(0, 300);
    continue;
  }
  const ids = (body && (body.identifiers || body.results || body.customers)) || [];
  if (Array.isArray(ids)) rows = rows.concat(ids);
}

const prior = Array.isArray(s.collected) ? s.collected : [];
const byId = new Map();
for (const r of prior) { const k = r.cio_id || r.id || r.email; if (k) byId.set(k, r); }
for (const r of rows) { const k = r.cio_id || r.id || r.email; if (k && !byId.has(k)) byId.set(k, r); }
const collected = Array.from(byId.values());

const attempt = (s.attempt || 0) + 1;
const enough = collected.length >= s.sampleSize;
const exhausted = attempt >= (s.maxAttempts || 3);
const done = enough || exhausted || !!error;

return [{ json: { ...s, attempt, collected, collectedCount: collected.length, totalMatching: collected.length, error, done } }];

const s = $('Collect & Check').first().json;
const samples = $('Sample Candidates').all().map(i => i.json).filter(x => x && !x.__empty);
const fetched = $input.all().map(i => i.json);

function attrsOf(resp) {
  return (resp && resp.customer && resp.customer.attributes) || {};
}

const candidates = samples.map((sm, idx) => {
  const a = attrsOf(fetched[idx] || {});
  const wf = a.wf_bucket;
  const services = a.services_bucket;
  const ai = a.ai_wfs_bucket;
  const age = a.days_bucket;
  const usage_summary = [
    wf !== undefined ? 'wf: ' + wf : null,
    services !== undefined ? 'services: ' + services : null,
    ai !== undefined ? 'ai: ' + ai : null,
    age !== undefined ? 'age: ' + age : null
  ].filter(Boolean).join(', ');
  return {
    email: a.email || sm.email || null,
    id: sm.cio_id || sm.cust_id || null,
    country: a.country || null,
    cloud_plan: a.cloud_plan || null,
    cloud_plan_status: a.cloud_plan_status || null,
    role: a.utm_user_role || null,
    company_size: a.company_size || null,
    first_name: a.first_name || null,
    usage_summary
  };
});

const shardsWalked = Array.isArray(s.shardsUsed) ? s.shardsUsed.length : 0;
const poolEstimate = shardsWalked > 0 ? Math.round((s.collectedCount || 0) * (s.shardCount || 4096) / shardsWalked) : (s.collectedCount || 0);

return [{ json: {
  candidates,
  sampleSize: candidates.length,
  collectedCount: s.collectedCount || 0,
  totalMatchingEstimate: poolEstimate,
  mode: s.mode,
  filtersApplied: s.filters,
  shardsUsed: s.shardsUsed || [],
  error: null
} }];

const s = $input.first().json;
// Rebuild the state for another Pick Shards pass. baseAndClauses persists.
return [{ json: {
  mode: s.mode, filters: s.filters, sampleSize: s.sampleSize, excludeRecentDays: s.excludeRecentDays,
  cooldownField: s.cooldownField, shardField: s.shardField, shardCount: s.shardCount,
  baseAndClauses: s.baseAndClauses, attempt: s.attempt, maxAttempts: s.maxAttempts,
  shardsUsed: s.shardsUsed, collected: s.collected, totalMatching: s.totalMatching
} }];

const s = $input.first().json;
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
const collected = Array.isArray(s.collected) ? s.collected : [];
const sampled = shuffle(collected).slice(0, s.sampleSize);
if (sampled.length === 0) return [{ json: { __empty: true } }];
return sampled.map(r => ({ json: { cio_id: r.cio_id || null, cust_id: r.id || null, email: r.email || null } }));
